import{_ as a,C as r,o as n,c as h,aj as d,E as o}from"./framework.js";const u=JSON.parse('{"title":"控制台：域名 | Product / Console | Documentation","description":"控制台：域名 in Kooboo: 域名页管理的是“账户拥有的域名”。如果你要把域名设为某个站点的访问入口，还需要在站点后台继续配置 CMS：域名管理。","frontmatter":{"title":"控制台：域名 | Product / Console | Documentation","description":"控制台：域名 in Kooboo: 域名页管理的是“账户拥有的域名”。如果你要把域名设为某个站点的访问入口，还需要在站点后台继续配置 CMS：域名管理。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/console/domains.html"}]]},"headers":[],"relativePath":"zh/product/console/domains.md","filePath":"product/console/domains.md","lastUpdated":1780996899000}'),c={name:"zh/product/console/domains.md"};function i(s,t,l,b,p,m){const e=r("DocImage");return n(),h("div",null,[t[0]||(t[0]=d('<h1 id="控制台-域名" tabindex="-1">控制台：域名 <a class="header-anchor" href="#控制台-域名" aria-label="Permalink to &quot;控制台：域名&quot;">​</a></h1><blockquote><p>管理账户下的域名资产：添加已有域名、购买新域名、绑定站点、维护 DNS、续费、转移码与数据中心。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>控制台</strong> -&gt; 左侧 <strong>域名</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kconsole</code></td></tr><tr><td>前端路由</td><td><code>/kconsole</code></td></tr><tr><td>可见身份</td><td>所有组织成员可见；购买、续费、DNS、数据中心等动作通常需要组织管理员</td></tr></tbody></table><p>域名页管理的是“账户拥有的域名”。如果你要把域名设为某个站点的访问入口，还需要在站点后台继续配置 <a href="/kb-docs/zh/cms/settings/domains.html">CMS：域名管理</a>。</p>',5)),o(e,{src:"/product/console/domains-overview.png",alt:"控制台域名列表",width:"1120"}),t[1]||(t[1]=d('<h2 id="域名列表" tabindex="-1">域名列表 <a class="header-anchor" href="#域名列表" aria-label="Permalink to &quot;域名列表&quot;">​</a></h2><p>页面顶部工具栏：</p><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td><code>新建</code></td><td>添加已有域名到当前账户</td></tr><tr><td><code>域名购买</code></td><td>组织管理员可见，进入域名搜索与购买页</td></tr></tbody></table><p>列表重点：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>域名</td><td>点击域名名称进入 <strong>域名绑定</strong> 子页</td></tr><tr><td>数据中心</td><td>在线服务环境显示；管理员可点击后更换域名数据中心</td></tr><tr><td>到期时间</td><td>域名到期日期</td></tr><tr><td>Record</td><td>DNS 记录数量</td></tr><tr><td>Site</td><td>绑定站点数量</td></tr><tr><td>Action</td><td>在线服务环境显示，含续费、转移码、DNS 设置等动作</td></tr></tbody></table><h2 id="添加已有域名" tabindex="-1">添加已有域名 <a class="header-anchor" href="#添加已有域名" aria-label="Permalink to &quot;添加已有域名&quot;">​</a></h2><p>点击 <code>新建</code> 后会打开 <strong>New Local Domain</strong> 弹窗。</p><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>DNS 提示</td><td>在线服务环境会提示可用 DNS Server，以及可用于通配域名的 CNAME</td></tr><tr><td><code>Domain</code></td><td>填入要接入账户的根域名，例如 <code>example.com</code></td></tr><tr><td><code>Create</code></td><td>保存后返回域名列表</td></tr></tbody></table><p>添加后先观察列表里的 <code>Record</code>、<code>Site</code> 和到期时间，再决定是否进入 DNS 或绑定页。</p><h2 id="绑定站点" tabindex="-1">绑定站点 <a class="header-anchor" href="#绑定站点" aria-label="Permalink to &quot;绑定站点&quot;">​</a></h2><p>从域名列表点击域名名称，会进入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/kconsole/DomainBinding?id={domainId}</span></span></code></pre></div>',12)),o(e,{src:"/product/console/domains-binding.png",alt:"控制台域名绑定列表",width:"1120"}),t[2]||(t[2]=d('<p>绑定页顶部有 <code>新建</code> 按钮，列表显示：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Domain</td><td>完整绑定域名，例如 <code>www.example.com</code></td></tr><tr><td>Site</td><td>已绑定站点名称；点击会打开 <code>/_Admin/site?SiteId={siteId}</code></td></tr><tr><td>Preview</td><td>用当前域名预览站点</td></tr></tbody></table><p>新建绑定弹窗需要填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td><code>Domain</code></td><td>子域名前缀，例如 <code>www</code>；右侧会自动拼接当前根域名</td></tr><tr><td><code>Site</code></td><td>从当前账户的站点列表中选择要绑定的站点</td></tr></tbody></table><p>保存后，建议回到 <a href="/kb-docs/zh/cms/settings/domains.html">CMS：域名管理</a> 检查站点侧域名、主域名和 SSL 状态。</p><h2 id="dns-记录" tabindex="-1">DNS 记录 <a class="header-anchor" href="#dns-记录" aria-label="Permalink to &quot;DNS 记录&quot;">​</a></h2><p>从域名列表的 DNS 设置动作进入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/kconsole/domainDNS?domainName=example.com</span></span></code></pre></div>',8)),o(e,{src:"/product/console/domains-dns.png",alt:"控制台 DNS 记录列表",width:"1120"}),t[3]||(t[3]=d('<p>DNS 记录页顶部有 <code>添加</code> 按钮，表格显示：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Host</td><td>主机记录</td></tr><tr><td>Record Type</td><td>记录类型</td></tr><tr><td>Record Value</td><td>记录值</td></tr><tr><td>TTL</td><td>缓存时间</td></tr></tbody></table><p>添加记录弹窗：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>Host Record</code></td><td>主机记录，右侧会拼接当前域名</td></tr><tr><td><code>Record Type</code></td><td>从后端返回的 DNS 类型列表中选择</td></tr><tr><td><code>Record Value</code></td><td>目标值，例如 IP、CNAME、TXT 内容等</td></tr><tr><td><code>Priority</code></td><td>仅 <code>MX</code> 类型显示</td></tr><tr><td><code>TTL</code></td><td>从预设 TTL 列表中选择</td></tr></tbody></table><p>页面底部有返回按钮，保存或删除记录后列表会刷新。</p><h2 id="购买域名" tabindex="-1">购买域名 <a class="header-anchor" href="#购买域名" aria-label="Permalink to &quot;购买域名&quot;">​</a></h2><p>组织管理员点击 <code>域名购买</code> 进入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/kconsole/domainSearch</span></span></code></pre></div>',8)),o(e,{src:"/product/console/domains-search.png",alt:"控制台域名购买搜索页",width:"1120"}),t[4]||(t[4]=d('<p>搜索区包含：</p><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td>搜索框</td><td>输入域名前缀，例如 <code>kooboo</code>；也可以输入带后缀的域名</td></tr><tr><td>后缀复选框</td><td>默认选中 <code>.com</code>、<code>.net</code>、<code>.site</code>、<code>.dev</code>，可追加其它后缀</td></tr><tr><td><code>Search</code></td><td>搜索可注册状态与价格</td></tr></tbody></table><p>结果列表显示域名、价格、状态与 <code>Immediately Get</code> 操作。可注册域名点击后会打开创建订单弹窗：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Domain</td><td>当前选择的域名，只读</td></tr><tr><td>Period</td><td>年限，1 到 10 年</td></tr><tr><td>Amount</td><td>按价格和年限计算出的总额</td></tr><tr><td>Contact Information</td><td>可选择自动使用 Kooboo 信息，或自定义姓名、电话、邮箱、地址</td></tr></tbody></table><p>确认后会生成订单并跳转到 <a href="./orders.html#结账页">订单结账页</a>。</p><h2 id="续费、转移码与数据中心" tabindex="-1">续费、转移码与数据中心 <a class="header-anchor" href="#续费、转移码与数据中心" aria-label="Permalink to &quot;续费、转移码与数据中心&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>从哪里点</th><th>后续页面</th></tr></thead><tbody><tr><td>续费</td><td>域名列表 Action 列的 <code>Renew</code></td><td>选择续费年限后进入 <a href="./orders.html#结账页">结账页</a></td></tr><tr><td>转移码</td><td>域名列表 Action 列的转移图标</td><td>弹窗展示 transfer code</td></tr><tr><td>更换数据中心</td><td>点击数据中心列</td><td>选择目标数据中心，确认后保存</td></tr></tbody></table><p>域名续费弹窗的年限范围是 1 到 10 年。保存后会创建域名续费订单，而不是直接扣费。</p><h2 id="常见工作流" tabindex="-1">常见工作流 <a class="header-anchor" href="#常见工作流" aria-label="Permalink to &quot;常见工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>接入已有域名</td><td>新建 -&gt; 按提示配置 DNS Server 或 CNAME -&gt; 域名绑定 -&gt; 回 CMS 域名管理核对</td></tr><tr><td>购买新域名并建站</td><td>域名购买 -&gt; 创建订单 -&gt; 结账 -&gt; 域名绑定 -&gt; 回 CMS 配置主域名</td></tr><tr><td>给域名补 DNS 记录</td><td>域名列表 -&gt; DNS 设置 -&gt; 添加记录 -&gt; 回外部工具验证解析</td></tr><tr><td>域名即将到期</td><td>域名列表 -&gt; 续费 -&gt; 结账页付款 -&gt; 续费页复核</td></tr></tbody></table><h2 id="与站点后台的分工" tabindex="-1">与站点后台的分工 <a class="header-anchor" href="#与站点后台的分工" aria-label="Permalink to &quot;与站点后台的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控制台域名</th><th>CMS 域名管理</th></tr></thead><tbody><tr><td>账户级域名资产、DNS、购买、续费、转移码、数据中心</td><td>某个站点的域名绑定、Base URL、主域名、SSL</td></tr><tr><td>深链 <code>/_Admin/kconsole</code></td><td>深链 <code>/_Admin/system/domains?SiteId={GUID}</code></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../console.html">控制台概述</a></td><td>控制台菜单地图</td></tr><tr><td><a href="./orders.html">订单</a></td><td>域名购买、续费后的支付页</td></tr><tr><td><a href="./renewals.html">续费</a></td><td>查看域名续费项</td></tr><tr><td><a href="/kb-docs/zh/cms/settings/domains.html">CMS：域名管理</a></td><td>站点级域名配置</td></tr></tbody></table>',14))])}const S=a(c,[["render",i]]);export{u as __pageData,S as default};
